<?php
namespace App\Jobs;
use App\Models\EmailCampaignRecipient; use App\Models\PlatformLead; use App\Models\MarketingSuppression; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Mail; use Illuminate\Support\Facades\URL;
class SendPromotionalEmailJob implements ShouldQueue {use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public $tries=3;public function __construct(public int $recipientId){}public function handle(){ $r=EmailCampaignRecipient::with('campaign')->find($this->recipientId);if(!$r||!in_array($r->status,['queued','pending']))return;if($r->campaign->status==='cancelled'){$r->update(['status'=>'cancelled']);return;}$lead=PlatformLead::where('email',$r->email)->first();if($lead?->unsubscribed||MarketingSuppression::where('email',$r->email)->exists()){$r->update(['status'=>'unsubscribed']);return;}$url=URL::temporarySignedRoute('marketing.unsubscribe',now()->addYear(),['email'=>$r->email]);$body=str_replace(['{{name}}','{{school_name}}'],[$r->name?:'there',$r->school_name?:'your school'],$r->campaign->html_body);$body.='<hr><p style="font-size:12px;color:#666">You are receiving this Skulag promotional message. <a href="'.$url.'">Unsubscribe</a></p>';try{Mail::html($body,function($m)use($r,$url){$m->to($r->email,$r->name)->subject($r->campaign->subject);$m->getSymfonyMessage()->getHeaders()->addTextHeader('List-Unsubscribe','<'.$url.'>');$m->getSymfonyMessage()->getHeaders()->addTextHeader('List-Unsubscribe-Post','List-Unsubscribe=One-Click');});$r->update(['status'=>'sent','sent_at'=>now()]);$r->campaign()->increment('sent_count');}catch(\Throwable $e){$r->update(['status'=>'failed','error'=>substr($e->getMessage(),0,1000)]);$r->campaign()->increment('failed_count');throw $e;}}
}
